#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
BOARD_ARG="${1:-b1-beta-c}"
TOOLBIN="${TOOLBIN:-/Applications/STM32CubeIDE.app/Contents/Eclipse/plugins/com.st.stm32cube.ide.mcu.externaltools.gnu-tools-for-stm32.13.3.rel1.macos64_1.0.0.202411102158/tools/bin}"

source "${ROOT_DIR}/scripts/board_env.sh" "${BOARD_ARG}"

export PATH="${TOOLBIN}:${PATH}"
export OBJCOPY="${OBJCOPY:-${TOOLBIN}/arm-none-eabi-objcopy}"
export POWERLYTICS_BOARD_SLUG
export POWERLYTICS_BOARD_SKU

cat > "${ROOT_DIR}/Core/Inc/board_active_config.h" <<EOF
/* Auto-generated by scripts/build_board.sh. Do not commit. */
#ifndef BOARD_ACTIVE_CONFIG_H
#define BOARD_ACTIVE_CONFIG_H

#define POWERLYTICS_ACTIVE_BOARD ${POWERLYTICS_BOARD_MACRO}

#endif /* BOARD_ACTIVE_CONFIG_H */
EOF

echo "Building Powerlytics board ${POWERLYTICS_BOARD_SKU} (${POWERLYTICS_BOARD_MACRO})"

make -C "${ROOT_DIR}/Bootloader" clean all
make -C "${ROOT_DIR}/Debug" clean all

"${ROOT_DIR}/scripts/package_current_artifacts.sh"

echo "Built ${POWERLYTICS_BOARD_SKU} artifacts in ${ROOT_DIR}/artifacts/boards/${POWERLYTICS_BOARD_SLUG}"
